def solve(n,edges,s):
    import heapq
    g=[[] for _ in range(n)]
    for a,b,w in edges: g[a].append((b,w))
    d=[float("inf")]*n
    d[s]=0
    q=[(0,s)]
    while q:
        dist,u=heapq.heappop(q)
        if dist!=d[u]: continue
        for v,w in g[u]:
            if dist+w<d[v]:
                d[v]=dist+w
                heapq.heappush(q,(d[v],v))
    return [-1 if x==float("inf") else x for x in d]
